import * as Sentry from "@sentry/react-native";
import type { ErrorEvent } from "@sentry/core";
import type { ReactNativeOptions } from "@sentry/react-native";
import { env } from "@/lib/env";

// App-hang detection options forwarded to the native iOS SDK. The React Native
// wrapper passes unrecognized init keys straight through to sentry-cocoa's
// SentryOptions (verified in sentry-cocoa 8.58.0, bundled with
// @sentry/react-native 7.11), but the wrapper's TypeScript types don't declare
// them yet, so they're typed here.
type NativeAppHangOptions = {
  enableAppHangTrackingV2?: boolean;
  enableReportNonFullyBlockingAppHangs?: boolean;
};

export const navigationIntegration = Sentry.reactNavigationIntegration({
  enableTimeToInitialDisplay: true,
});

// Drop transient, non-actionable failures that flood Sentry as handled
// exceptions (issue 7336845703). Self-sufficient signals are dropped anywhere;
// generic native network errors are dropped only when a download/asset context
// co-occurs, so an actionable failure on another path with the same cause still
// reports. HTTP-status failures like "response has status 404" are kept.
const TRANSIENT_MARKERS = [
  "The network connection was lost.",
  "The request timed out.",
  "The Internet connection appears to be offline.",
  "Could not connect to the server.",
  "A server with the specified hostname could not be found.",
  "Unable to download asset from url:",
  "SERVICE_NOT_AVAILABLE",
  // FCM refused to issue a device token because this installation has reached
  // the per-device registration limit (common on emulators and restored
  // devices). Device state, not an app defect; retried on the next launch.
  "TOO_MANY_REGISTRATIONS",
  // Firebase Installations failed to authenticate the device (clock skew,
  // restored backups reusing another device's installation ID, flaky Play
  // Services). The push-token fetch is re-attempted on the next app launch,
  // and AUTHENTICATION_FAILED (a real FCM misconfiguration) still reports.
  "FIS_AUTH_ERROR",
  "Notifications are not allowed for this application",
  "Network request failed",
  "Network request timed out",
  "User interaction is not allowed",
];

const NATIVE_NETWORK_MARKERS = [
  "SocketTimeoutException",
  "SocketException",
  "UnknownHostException",
  "ConnectException",
  "ConnectionShutdownException",
  "StreamResetException",
];

const DOWNLOAD_CONTEXT_MARKERS = ["downloadFileAsync", "ExpoAsset.downloadAsync", "Unable to download"];

// "Unable to resolve data for blob: <uuid>" fires when iOS purges React Native's blob-backed
// response storage while the app is suspended, and something later tries to read that body.
// Reads that go through lib/request.ts are converted to StaleResponseError and retried; what
// reaches Sentry is the frameless leftover surfaced via onunhandledrejection from native code
// (no app frames, nothing to fix, the rejection is already handled by RN). Only those frameless
// leftovers are dropped — a stale-blob read that carries app stack frames points at a call site
// outside lib/request.ts and must still report. 4,771 events / 0 crashes as of 2026-07:
// https://gumroad-to.sentry.io/issues/7376092087/
const STALE_BLOB_MARKERS = ["Unable to resolve data for blob", "The specified blob is invalid"];

// Gateway/capacity failures from the API (502 bad gateway, 503 unavailable, 504 gateway
// timeout) are upstream infrastructure conditions, not mobile defects: the request layer
// already retries GETs once and react-query retries queries with backoff, and screens show
// their error states. Reporting each occurrence here produced 9K+ events with nothing to fix
// on this side (issue 7376627649). Plain 500s are NOT dropped — a malformed request built by
// the app can surface as a 500, and those need eyes.
const GATEWAY_ERROR_MARKERS = ["Request failed: 502", "Request failed: 503", "Request failed: 504"];

const hasAppFrames = (event: ErrorEvent) =>
  (event.exception?.values ?? []).some((value) => (value.stacktrace?.frames ?? []).some((frame) => frame.in_app));

const isNonActionableError = (event: ErrorEvent) => {
  const values = event.exception?.values;
  if (!values) return false;
  // A session that ended — a revoked or expired refresh token, or a sign-out racing an in-flight
  // refresh — is an expected state, not a defect: the request paths already turn it into a sign-out.
  // Match the type rather than the message so a new variant of it is covered too.
  const primaryType = values[0]?.type;
  if (primaryType === "AbortError" || primaryType === "UnauthorizedError" || primaryType === "SessionExpiredError")
    return true;
  const text = values.map((value) => `${value.type ?? ""}: ${value.value ?? ""}`).join("\n");
  if (TRANSIENT_MARKERS.some((marker) => text.includes(marker))) return true;
  if (STALE_BLOB_MARKERS.some((marker) => text.includes(marker)) && !hasAppFrames(event)) return true;
  if (GATEWAY_ERROR_MARKERS.some((marker) => text.includes(marker))) return true;
  return (
    DOWNLOAD_CONTEXT_MARKERS.some((marker) => text.includes(marker)) &&
    NATIVE_NETWORK_MARKERS.some((marker) => text.includes(marker))
  );
};

const options: ReactNativeOptions & NativeAppHangOptions = {
  dsn: env.EXPO_PUBLIC_SENTRY_DSN,
  tracesSampleRate: __DEV__ ? 1 : 0.1,
  // Reduce from default 100 to 30 to prevent main-thread hangs.
  // SentryCrashScopeObserver serializes all breadcrumbs to JSON on the main
  // thread via addEscapedString, which blocks for 2000ms+ with 100 breadcrumbs.
  // See: https://gumroad-to.sentry.io/issues/7435371854/
  maxBreadcrumbs: 30,
  // Use v2 app-hang detection on iOS. The default (v1) detector falsely reports
  // "App Hanging: at least 2000 ms" when iOS suspends the app mid-run-loop
  // (backgrounding, PDF text selection, OS framework work) — the sampled stacks
  // on https://gumroad-to.sentry.io/issues/7384299696/ are almost all
  // didEnterBackground/fsync and system frameworks, not app code. V2 cancels
  // hangs interrupted by backgrounding and reports the actual hang duration.
  enableAppHangTrackingV2: true,
  // Non-fully-blocking hangs (the run loop still processes some events) are not
  // user-visible freezes; only report hangs where the main thread is truly stuck.
  enableReportNonFullyBlockingAppHangs: false,
  // Session replay disabled: the native SentrySessionReplay.createAndCaptureInBackground
  // method blocks the main thread for 2000ms+, causing app hangs on iOS.
  // See: https://github.com/getsentry/sentry-react-native/issues/4838
  // Re-enable once the upstream fix lands in @sentry/react-native.
  replaysSessionSampleRate: 0,
  replaysOnErrorSampleRate: 0,
  beforeSend(event) {
    if (isNonActionableError(event)) {
      return null;
    }
    return event;
  },
  integrations: [navigationIntegration],
};

Sentry.init(options);

export { Sentry };
