import { StyledWebView } from "@/components/styled";
import { Button } from "@/components/ui/button";
import { LoadingSpinner } from "@/components/ui/loading-spinner";
import { Screen } from "@/components/ui/screen";
import { Text } from "@/components/ui/text";
import { env } from "@/lib/env";
import { safeOpenURL } from "@/lib/open-url";
import { downloadFileWithRetry, FileUnavailableError } from "@/lib/file-utils";
import { getExportAllSalesUrl } from "@/lib/sales-export";
import { useWebViewSession } from "@/lib/use-webview-session";
import * as Sentry from "@sentry/react-native";
import { File, Paths } from "expo-file-system";
import { Stack } from "expo-router";
import { shareFile } from "@/lib/share";
import { useCallback, useState } from "react";
import { Alert, View } from "react-native";
import type { WebViewHttpErrorEvent } from "react-native-webview/lib/WebViewTypes";

const gumroadOrigin = new URL(env.EXPO_PUBLIC_GUMROAD_URL).origin;

const webViewInternalSchemes = ["about:", "data:", "blob:", "javascript:"];

const isWebViewInternalUrl = (url: string) => {
  const lower = url.toLowerCase();
  return webViewInternalSchemes.some((scheme) => lower.startsWith(scheme));
};

const isGumroadUrl = (url: string) => {
  try {
    return new URL(url).origin === gumroadOrigin;
  } catch {
    return false;
  }
};

const SALES_CSV_FILE_NAME = "sales.csv";
const HTML_TAG_OPEN_BYTE = "<".charCodeAt(0);
const LARGE_EXPORT_MESSAGE = "Large exports arrive by email.";

const readFirstByte = async (file: File) => {
  const handle = file.open();
  try {
    return (await handle.readBytes(1))[0];
  } finally {
    handle.close();
  }
};

const downloadSalesExportFile = async (url: string) => {
  const file = new File(Paths.cache, SALES_CSV_FILE_NAME);
  // The export URL is derived from the access token, so there is no fresher URL to fetch on a
  // 404 — the helper retries the same URL once.
  await downloadFileWithRetry(url, file);
  let firstByte = await readFirstByte(file);

  if (firstByte === undefined) {
    // A zero-byte file means the transfer was cut off even though the download reported
    // success; a second attempt usually completes, so retry once before giving up.
    try {
      file.delete();
    } catch {}
    await downloadFileWithRetry(url, file);
    firstByte = await readFirstByte(file);
  }

  const failureMessage =
    firstByte === undefined
      ? "Failed to download file"
      : firstByte === HTML_TAG_OPEN_BYTE
        ? LARGE_EXPORT_MESSAGE
        : null;

  if (failureMessage !== null) {
    try {
      file.delete();
    } catch {}
    throw new Error(failureMessage);
  }
  return file;
};

export default function SalesExportScreen() {
  const [isDownloading, setIsDownloading] = useState(false);
  const {
    accessToken,
    handleAuthenticationHttpError,
    handleAuthenticationNavigation,
    handleSessionLoad,
    handleSessionLoadError,
    isLoading,
    url,
    webViewKey,
  } = useWebViewSession(getExportAllSalesUrl);

  const handleShouldStartLoadWithRequest = useCallback(
    (request: { url: string; mainDocumentURL?: string }) => {
      if (request.mainDocumentURL && request.url !== request.mainDocumentURL) return true;
      if (handleAuthenticationNavigation(request.url)) return false;
      if (request.url === url || isWebViewInternalUrl(request.url) || isGumroadUrl(request.url)) return true;
      safeOpenURL(request.url);
      return false;
    },
    [handleAuthenticationNavigation, url],
  );

  const downloadSalesExport = useCallback(async () => {
    if (url === null) return;
    setIsDownloading(true);
    try {
      const downloaded = await downloadSalesExportFile(url);
      await shareFile(downloaded.uri, {
        UTI: "public.comma-separated-values-text",
        mimeType: "text/csv",
        dialogTitle: "Export all sales",
      });
    } catch (error) {
      if (error instanceof Error && error.message === LARGE_EXPORT_MESSAGE) {
        Alert.alert("Large export", LARGE_EXPORT_MESSAGE);
      } else {
        if (!(error instanceof FileUnavailableError)) Sentry.captureException(error);
        Alert.alert("Download failed", error instanceof Error ? error.message : "Failed to download file");
      }
    } finally {
      setIsDownloading(false);
    }
  }, [url]);

  if (isLoading || url === null) {
    return (
      <View className="flex-1 items-center justify-center bg-body-bg">
        <LoadingSpinner size="large" />
      </View>
    );
  }

  return (
    <Screen>
      <Stack.Screen options={{ title: "Export all sales" }} />
      <StyledWebView
        key={webViewKey}
        source={{ uri: url }}
        className="flex-1 bg-transparent"
        webviewDebuggingEnabled
        incognito
        pullToRefreshEnabled
        thirdPartyCookiesEnabled
        originWhitelist={["*"]}
        onShouldStartLoadWithRequest={handleShouldStartLoadWithRequest}
        onLoad={(event) => {
          handleSessionLoad({ token: accessToken, url: event.nativeEvent.url });
        }}
        onError={() => {
          handleSessionLoadError({ token: accessToken });
        }}
        onHttpError={(event: WebViewHttpErrorEvent) => {
          handleAuthenticationHttpError(event.nativeEvent);
        }}
      />
      <View className="border-t border-border bg-body-bg p-4">
        <Button onPress={downloadSalesExport} disabled={isDownloading}>
          <Text>{isDownloading ? "Downloading..." : "Download CSV"}</Text>
        </Button>
      </View>
      {isDownloading && (
        <View className="absolute inset-0 items-center justify-center bg-black/50">
          <LoadingSpinner size="large" />
        </View>
      )}
    </Screen>
  );
}
