'use client'

// src/checkbox.tsx
import { Slot } from "@rn-primitives/slot";
import * as React from "react";
import { Pressable, View } from "react-native";
var CheckboxContext = React.createContext(null);
var Root = ({
  asChild,
  disabled = false,
  checked,
  onCheckedChange,
  ref,
  ...props
}) => {
  return <CheckboxContext.Provider
    value={{
      disabled,
      checked,
      onCheckedChange
    }}
  >
      <Trigger ref={ref} {...props} />
    </CheckboxContext.Provider>;
};
Root.displayName = "RootNativeCheckbox";
function useCheckboxContext() {
  const context = React.useContext(CheckboxContext);
  if (!context) {
    throw new Error(
      "Checkbox compound components cannot be rendered outside the Checkbox component"
    );
  }
  return context;
}
var Trigger = ({ asChild, onPress: onPressProp, ref, ...props }) => {
  const { disabled, checked, onCheckedChange } = useCheckboxContext();
  function onPress(ev) {
    if (disabled) return;
    const newValue = !checked;
    onCheckedChange(newValue);
    onPressProp?.(ev);
  }
  const Component = asChild ? Slot : Pressable;
  return <Component
    ref={ref}
    aria-disabled={disabled}
    role='checkbox'
    aria-checked={checked}
    onPress={onPress}
    accessibilityState={{
      checked,
      disabled
    }}
    disabled={disabled}
    {...props}
  />;
};
Trigger.displayName = "TriggerNativeCheckbox";
var Indicator = ({ asChild, forceMount, ref, ...props }) => {
  const { checked, disabled } = useCheckboxContext();
  if (!forceMount) {
    if (!checked) {
      return null;
    }
  }
  const Component = asChild ? Slot : View;
  return <Component
    ref={ref}
    aria-disabled={disabled}
    aria-hidden={!(forceMount || checked)}
    role={"presentation"}
    {...props}
  />;
};
Indicator.displayName = "IndicatorNativeCheckbox";
export {
  Indicator,
  Root
};
