import {
  getPendingAudioRestore,
  isAudioProgressDeferred,
  isAudioRestorePending,
  resolvePendingAudioRestore,
  setPendingAudioRestore,
  setAudioPlaybackIntent,
  setPendingAudioPlaybackIntent,
} from "@/lib/audio-seek";
import { setAudioAccessToken, setAudioContext } from "@/lib/audio-player-store";
import { useAuth } from "@/lib/auth-context";
import {
  isMeaningfulLocation,
  isNearEndLocation,
  isResumableLocation,
  updateMediaLocation,
} from "@/lib/media-location";
import React, { useCallback, useEffect, useRef, useState } from "react";
import TrackPlayer, { Capability, Event, RepeatMode, State } from "react-native-track-player";
import type { WebView } from "react-native-webview";
import { getStoredLoopEnabled, getStoredPlaybackSpeed } from "./full-audio-player";

type AudioPlayerInfo = {
  fileId: string;
  isPlaying: boolean;
  latestMediaLocation?: string;
};

export type AudioTrackInfo = {
  uri: string;
  resourceId: string;
  title?: string;
  urlRedirectId?: string;
  purchaseId?: string;
  resumeAt?: number;
  contentLength?: number;
};

let isPlayerSetup = false;
let playerSetupListeners: (() => void)[] = [];
let hasRestoredSavedPosition = false;
const ENDED_POSITION_TOLERANCE = 0.5;

export const isPlayerInitialized = () => isPlayerSetup;

export const withPlayerReady = <P extends object>(Component: React.ComponentType<P>): React.FC<P> => {
  const Wrapped: React.FC<P> = (props) => {
    const [ready, setReady] = useState(isPlayerSetup);
    useEffect(() => {
      if (isPlayerSetup) {
        setReady(true);
        return;
      }
      const listener = () => setReady(true);
      playerSetupListeners.push(listener);
      return () => {
        playerSetupListeners = playerSetupListeners.filter((l) => l !== listener);
      };
    }, []);
    if (!ready) return null;
    return React.createElement(Component, props);
  };
  return Wrapped;
};

export const setupPlayer = async () => {
  if (isPlayerSetup) return;

  try {
    await TrackPlayer.setupPlayer();
  } catch (error) {
    // On Android the playback service can outlive the JS bundle (background playback keeps it
    // running after the app is swiped away). When JS starts again over that live service,
    // setupPlayer rejects with this code even though the player is fully usable. Treating it
    // as a failure left isPlayerSetup false forever, so every audio tap was silently ignored.
    const isAlreadyInitialized =
      error instanceof Error && "code" in error && error.code === "player_already_initialized";
    if (!isAlreadyInitialized) throw error;
  }
  await TrackPlayer.updateOptions({
    capabilities: [
      Capability.Play,
      Capability.Pause,
      Capability.Stop,
      Capability.SkipToNext,
      Capability.SkipToPrevious,
      Capability.JumpForward,
      Capability.JumpBackward,
    ],
    notificationCapabilities: [
      Capability.Play,
      Capability.Pause,
      Capability.SkipToNext,
      Capability.SkipToPrevious,
      Capability.JumpForward,
      Capability.JumpBackward,
    ],
    forwardJumpInterval: 30,
    backwardJumpInterval: 15,
    android: {
      audioOffload: false,
    },
  });
  const loopEnabled = await getStoredLoopEnabled();
  await TrackPlayer.setRepeatMode(loopEnabled ? RepeatMode.Queue : RepeatMode.Off);
  isPlayerSetup = true;
  playerSetupListeners.forEach((l) => l());
  playerSetupListeners = [];
};

export const useAudioPlayerSync = (webViewRef: React.RefObject<WebView | null>) => {
  const { accessToken } = useAuth();
  const [activeResourceId, setActiveResourceId] = useState<string | null>(null);
  const [isPlaying, setIsPlaying] = useState(false);

  useEffect(() => {
    setAudioAccessToken(accessToken);
  }, [accessToken]);

  const currentAudioRef = useRef<{
    resourceId: string;
    urlRedirectId?: string;
    purchaseId?: string;
    contentLength?: number;
  } | null>(null);

  const allTracksRef = useRef<AudioTrackInfo[]>([]);

  useEffect(() => {
    const initFromPlayer = async () => {
      if (!isPlayerSetup) return;
      const activeTrack = await TrackPlayer.getActiveTrack();
      const { state } = await TrackPlayer.getPlaybackState();
      if (activeTrack?.id && (state === State.Playing || state === State.Buffering)) {
        setActiveResourceId(activeTrack.id);
        setIsPlaying(true);
      } else if (activeTrack?.id && state === State.Paused) {
        setActiveResourceId(activeTrack.id);
        setIsPlaying(false);
      } else {
        setActiveResourceId(null);
        setIsPlaying(false);
      }

      const queue = await TrackPlayer.getQueue();
      if (queue.length > 0) {
        allTracksRef.current = queue.map((t) => ({
          uri: t.url?.toString() ?? "",
          resourceId: t.id ?? "",
          title: t.title,
          urlRedirectId: t.urlRedirectId,
          purchaseId: t.purchaseId,
          resumeAt: t.resumeAt,
          contentLength: t.contentLength,
        }));
      }
      if (activeTrack?.id) {
        const track = allTracksRef.current.find((t) => t.resourceId === activeTrack.id);
        if (track) {
          currentAudioRef.current = { ...track, contentLength: activeTrack.duration ?? track.contentLength };
          setAudioContext(currentAudioRef.current);
          if (!hasRestoredSavedPosition && state !== State.Playing && state !== State.Buffering) {
            const { position, duration } = await TrackPlayer.getProgress();
            if (!isMeaningfulLocation(position, false) && track.resumeAt && !(duration > 0)) {
              setPendingAudioRestore({
                resourceId: track.resourceId,
                position: track.resumeAt,
                provisionalPosition: isResumableLocation(track.resumeAt, track.contentLength) ? track.resumeAt : 0,
              });
            }
            if (
              !isMeaningfulLocation(position, false) &&
              isResumableLocation(track.resumeAt, duration > 0 ? duration : track.contentLength) &&
              isMeaningfulLocation(track.resumeAt, false)
            ) {
              await TrackPlayer.seekTo(track.resumeAt);
              hasRestoredSavedPosition = true;
            }
          }
        }
      }
    };
    initFromPlayer();
  }, []);

  const syncMediaLocation = useCallback(
    async (position: number, isEnd = false) => {
      const currentAudio = currentAudioRef.current;
      if (
        !currentAudio ||
        !currentAudio.urlRedirectId ||
        isAudioProgressDeferred(currentAudio.resourceId) ||
        (isEnd && isAudioRestorePending(currentAudio.resourceId))
      )
        return;
      if (!isMeaningfulLocation(position, isEnd)) return;

      const location = isEnd && currentAudio.contentLength ? currentAudio.contentLength : Math.floor(position);

      await updateMediaLocation({
        urlRedirectId: currentAudio.urlRedirectId,
        productFileId: currentAudio.resourceId,
        purchaseId: currentAudio.purchaseId,
        location,
        accessToken,
      });
    },
    [accessToken],
  );

  const sendAudioPlayerInfo = useCallback(
    async ({
      isPlaying,
      isEnd: forceIsEnd,
      confirmObservation = false,
    }: {
      isPlaying: boolean;
      isEnd?: boolean;
      confirmObservation?: boolean;
    }) => {
      const currentAudio = currentAudioRef.current;
      if (!currentAudio) return;

      const progress = await TrackPlayer.getProgress();
      if (currentAudioRef.current !== currentAudio) return;
      const resolved = await resolvePendingAudioRestore(
        currentAudio.resourceId,
        progress,
        isPlaying || !!forceIsEnd,
        confirmObservation,
      );
      if (!resolved || currentAudioRef.current !== currentAudio) return;
      const { position, duration } = resolved;
      if (resolved.restored) forceIsEnd = false;
      if (duration > 0) currentAudio.contentLength = duration;
      const isStart = position < 1;
      const isEnd = forceIsEnd || isNearEndLocation(position, duration);

      webViewRef.current?.postMessage(
        JSON.stringify({
          type: "mobileAppAudioPlayerInfo",
          payload: {
            fileId: currentAudio.resourceId,
            isPlaying,
            latestMediaLocation: position.toString(),
          } satisfies AudioPlayerInfo,
        }),
      );

      const flooredPosition = Math.floor(position);
      if (!isPlaying || isStart || isEnd || flooredPosition % 5 === 0) {
        await syncMediaLocation(position, isEnd);
      }
    },
    [webViewRef, syncMediaLocation],
  );

  useEffect(() => {
    const intervalId = setInterval(async () => {
      if (!isPlayerSetup) {
        console.warn("Audio polling called before player setup");
        return;
      }
      const { state } = await TrackPlayer.getPlaybackState();
      if (state === State.Playing || getPendingAudioRestore()) {
        await sendAudioPlayerInfo({ isPlaying: state === State.Playing, isEnd: state === State.Ended });
      }
    }, 5000);

    const stateSubscription = TrackPlayer.addEventListener(Event.PlaybackState, async ({ state }) => {
      if (state === State.Playing || state === State.Buffering) {
        if (state === State.Playing) setPendingAudioPlaybackIntent(true);
        setIsPlaying(true);
      } else if (state === State.Paused || state === State.Stopped) {
        setPendingAudioPlaybackIntent(false);
        setIsPlaying(false);
        await sendAudioPlayerInfo({ isPlaying: false, confirmObservation: true });
      } else if (state === State.Ended) {
        setIsPlaying(false);
        setActiveResourceId(null);
        await sendAudioPlayerInfo({ isPlaying: false, isEnd: true });
      }
    });

    const endSubscription = TrackPlayer.addEventListener(Event.PlaybackQueueEnded, async () => {
      setIsPlaying(false);
      setActiveResourceId(null);
      await sendAudioPlayerInfo({ isPlaying: false, isEnd: true });
    });

    return () => {
      clearInterval(intervalId);
      stateSubscription.remove();
      endSubscription.remove();
      if (currentAudioRef.current) sendAudioPlayerInfo({ isPlaying: false });
    };
  }, [sendAudioPlayerInfo, syncMediaLocation]);

  const pauseAudio = useCallback(async () => {
    if (!isPlayerSetup) {
      console.warn("pauseAudio called before player setup");
      return;
    }
    setAudioPlaybackIntent(false);
    await TrackPlayer.pause();
    await sendAudioPlayerInfo({ isPlaying: false, confirmObservation: true });
  }, [sendAudioPlayerInfo]);

  const updateCurrentAudioRef = useCallback((resourceId: string, duration?: number) => {
    const track = allTracksRef.current.find((t) => t.resourceId === resourceId);
    if (track) {
      const context = { ...track, contentLength: duration ?? track.contentLength };
      currentAudioRef.current = context;
      setAudioContext(context);
    }
  }, []);

  useEffect(() => {
    const subscription = TrackPlayer.addEventListener(Event.PlaybackActiveTrackChanged, async (event) => {
      if (event.track?.id) {
        setActiveResourceId(event.track.id);
        const previousContext = currentAudioRef.current;
        if (previousContext && previousContext.resourceId !== event.track.id) {
          const position = event.lastPosition ?? 0;
          await syncMediaLocation(position);
        }
        if (getPendingAudioRestore()?.resourceId !== event.track.id) setPendingAudioRestore(null);
        updateCurrentAudioRef(event.track.id, event.track.duration);
      }
    });
    return () => subscription.remove();
  }, [syncMediaLocation, updateCurrentAudioRef]);

  const playAudioChainRef = useRef<Promise<void>>(Promise.resolve());

  const performPlayAudio = useCallback(
    async ({
      resourceId,
      resumeAt,
      artist,
      artistUrl,
      artwork,
      tracks,
    }: {
      resourceId: string;
      resumeAt?: number;
      artist?: string;
      artistUrl?: string;
      artwork?: string | null;
      tracks: AudioTrackInfo[];
    }) => {
      if (!isPlayerSetup) {
        console.warn("playAudio called before player setup");
        return;
      }
      const audio = tracks.find((track) => track.resourceId === resourceId);
      if (!audio) {
        console.warn(`Couldn't find track ${resourceId}. Available:`, tracks);
        return;
      }
      const previousContext = currentAudioRef.current;

      if (previousContext && previousContext.resourceId !== audio.resourceId) {
        const { position } = await TrackPlayer.getProgress();
        await syncMediaLocation(position);
      }

      const restoreSavedPosition = async () => {
        const resumePosition = resumeAt ?? audio.resumeAt;
        const { duration } = await TrackPlayer.getProgress();
        const provisionalPosition = isResumableLocation(resumePosition, audio.contentLength) ? resumePosition : 0;
        setPendingAudioRestore(
          resumePosition && !(duration > 0) ? { resourceId, position: resumePosition, provisionalPosition } : null,
        );
        if (isResumableLocation(resumePosition, duration > 0 ? duration : audio.contentLength)) {
          await TrackPlayer.seekTo(resumePosition);
        }
      };

      const loadPlaylist = async () => {
        setPendingAudioRestore(null);
        allTracksRef.current = tracks;
        await TrackPlayer.reset();
        await TrackPlayer.add(
          tracks.map((track) => ({
            id: track.resourceId,
            url: track.uri,
            title: track.title || "Audio Track",
            artist: artist || "Gumroad",
            artistUrl,
            artwork: artwork || undefined,
            urlRedirectId: track.urlRedirectId,
            purchaseId: track.purchaseId,
            resumeAt: track.resumeAt,
            contentLength: track.contentLength,
          })),
        );

        const trackIndex = tracks.findIndex((t) => t.resourceId === audio.resourceId);
        if (trackIndex > 0) {
          await TrackPlayer.skip(trackIndex);
        }

        await restoreSavedPosition();
      };

      const isNewPlaylist =
        !previousContext ||
        allTracksRef.current.length !== tracks.length ||
        !allTracksRef.current.every((t, i) => t.resourceId === tracks[i].resourceId);

      if (isNewPlaylist) {
        await loadPlaylist();
      } else if (previousContext?.resourceId !== audio.resourceId) {
        // Resolve the skip target against the NATIVE queue, not the JS track list.
        // The JS ref can say "same playlist" while the native player holds an empty
        // or different queue (the playback service restarted, or a reset happened
        // elsewhere) — skipping by a JS-derived index then throws
        // "The track index is out of bounds". If the track isn't in the native
        // queue, rebuild the playlist instead of skipping.
        const queue = await TrackPlayer.getQueue();
        const queueIndex = queue.findIndex((t) => t.id === audio.resourceId);
        if (queueIndex >= 0) {
          setPendingAudioRestore(null);
          await TrackPlayer.skip(queueIndex);
          await restoreSavedPosition();
        } else {
          await loadPlaylist();
        }
      } else {
        // Replaying the track that's already loaded. If it finished, the native player is
        // parked at the very end, so play() alone stops immediately — restart from the
        // beginning instead, matching how the web player treats finished tracks.
        const { state } = await TrackPlayer.getPlaybackState();
        const { position, duration } = await TrackPlayer.getProgress();
        if (state === State.Ended || (duration > 0 && position >= duration - ENDED_POSITION_TOLERANCE)) {
          setPendingAudioRestore(null);
          await TrackPlayer.seekTo(0);
        }
      }

      currentAudioRef.current = audio;
      setAudioContext(audio);

      const storedSpeed = await getStoredPlaybackSpeed();
      if (storedSpeed) await TrackPlayer.setRate(storedSpeed);

      setAudioPlaybackIntent(true);
      await TrackPlayer.play();
      await sendAudioPlayerInfo({ isPlaying: true });
    },
    [sendAudioPlayerInfo, syncMediaLocation],
  );

  // Serialize playAudio calls: two rapid taps can otherwise interleave
  // reset/add/skip across the async boundaries, leaving the second call
  // skipping into a queue the first call just cleared.
  const playAudio = useCallback(
    (options: Parameters<typeof performPlayAudio>[0]) => {
      const next = playAudioChainRef.current.catch(() => {}).then(() => performPlayAudio(options));
      playAudioChainRef.current = next;
      return next;
    },
    [performPlayAudio],
  );

  return { pauseAudio, playAudio, activeResourceId, isPlaying };
};
