import { useAuth } from "@/lib/auth-context";
import { requestAPI } from "@/lib/request";
import * as Sentry from "@sentry/react-native";
import * as Application from "expo-application";
import * as Notifications from "expo-notifications";
import { useRouter } from "expo-router";
import { useEffect, useRef } from "react";
import { Platform } from "react-native";

Notifications.setNotificationHandler({
  handleNotification: async () => ({
    shouldShowAlert: true,
    shouldPlaySound: true,
    shouldSetBadge: false,
    shouldShowBanner: true,
    shouldShowList: true,
  }),
});

const registerDeviceToken = async (expoPushToken: string, accessToken: string) => {
  const appVersion = Application.nativeApplicationVersion ?? "unknown";
  await requestAPI("/mobile/devices", {
    accessToken,
    method: "POST",
    data: {
      device: {
        token: expoPushToken,
        device_type: Platform.OS,
        app_type: "consumer",
        app_version: appVersion,
      },
    },
  });
};

export const SALES_NOTIFICATION_CHANNEL_ID = "sales";

// Android keeps a channel's sound from first creation across updates, and installs upgraded from the
// old native app hold a "Purchases" channel pointing at a resource id that no longer exists (silent).
// The new channel starts from the user's "Purchases" choice so sales they muted stay muted.
export const createAndroidNotificationChannels = async () => {
  const [legacyPurchases, existingSales] = await Promise.all([
    Notifications.getNotificationChannelAsync("Purchases"),
    Notifications.getNotificationChannelAsync(SALES_NOTIFICATION_CHANNEL_ID),
  ]);
  const inherited = !existingSales && legacyPurchases ? legacyPurchases : null;
  const salesImportance = inherited ? inherited.importance : Notifications.AndroidImportance.MAX;
  const salesSound = inherited && inherited.sound === null ? null : "chaching.wav";

  await Notifications.setNotificationChannelAsync("default", {
    name: "Default",
    importance: Notifications.AndroidImportance.MAX,
    vibrationPattern: [0, 250, 250, 250],
  });
  await Notifications.setNotificationChannelAsync("Purchases", {
    name: "Purchases",
    importance: Notifications.AndroidImportance.MAX,
    sound: "chaching.wav",
    vibrationPattern: [0, 250, 250, 250],
  });
  await Notifications.setNotificationChannelAsync(SALES_NOTIFICATION_CHANNEL_ID, {
    name: "Sales",
    importance: salesImportance,
    sound: salesSound,
    vibrationPattern: [0, 250, 250, 250],
  });
};

const getExpoPushToken = async () => {
  const { status: existingStatus } = await Notifications.getPermissionsAsync();
  let finalStatus = existingStatus;

  if (existingStatus !== "granted") {
    const { status } = await Notifications.requestPermissionsAsync();
    finalStatus = status;
  }

  if (finalStatus !== "granted") return null;

  if (Platform.OS === "android") await createAndroidNotificationChannels();

  const tokenData = await Notifications.getDevicePushTokenAsync();
  return tokenData.data;
};

const handledNotificationIdentifiers = new Set<string>();

let indexInitialRoutingComplete = false;

export const markIndexInitialRoutingComplete = () => {
  indexInitialRoutingComplete = true;
};

export const __resetPushNotificationsModuleStateForTests = () => {
  handledNotificationIdentifiers.clear();
  indexInitialRoutingComplete = false;
};

const buildNotificationRoute = (data: Record<string, any>): string | null => {
  if (!data.installment_id) return null;
  const params = new URLSearchParams();
  if (data.purchase_id) params.set("purchaseId", data.purchase_id);
  else if (data.subscription_id) params.set("subscriptionId", data.subscription_id);
  else if (data.follower_id) params.set("followerId", data.follower_id);
  const query = params.toString();
  return `/post/${data.installment_id}${query ? `?${query}` : ""}`;
};

export const consumeNotificationRoute = (
  response: Notifications.NotificationResponse | null,
): string | null => {
  if (!response) return null;
  const request = response.notification.request as {
    identifier: string;
    content?: { data?: Record<string, any> | null };
    trigger?: { payload?: Record<string, any> | null } | null;
  };
  const identifier = request.identifier;
  if (handledNotificationIdentifiers.has(identifier)) return null;
  const payloads = [request.content?.data, request.trigger?.payload];
  let route: string | null = null;
  for (const payload of payloads) {
    if (payload) route = buildNotificationRoute(payload);
    if (route) break;
  }
  if (!route) {
    Sentry.addBreadcrumb?.({
      category: "notifications",
      level: "warning",
      message: "Notification tapped but no post route was built",
      data: { contentData: request.content?.data ?? null, triggerPayload: request.trigger?.payload ?? null },
    });
    return null;
  }
  handledNotificationIdentifiers.add(identifier);
  return route;
};

export const usePushNotifications = () => {
  const { accessToken, isAuthenticated } = useAuth();
  const router = useRouter();
  const notificationResponseListener = useRef<Notifications.EventSubscription | null>(null);

  useEffect(() => {
    if (!isAuthenticated || !accessToken) return;

    getExpoPushToken()
      .then((token) => {
        if (token) registerDeviceToken(token, accessToken);
      })
      .catch((error) => {
        console.error("Failed to register for push notifications:", error);
        Sentry.captureException(error);
      });
  }, [isAuthenticated, accessToken]);

  useEffect(() => {
    notificationResponseListener.current = Notifications.addNotificationResponseReceivedListener((response) => {
      if (!indexInitialRoutingComplete) return;
      const route = consumeNotificationRoute(response);
      if (!route) return;
      router.push(route as any);
      Notifications.clearLastNotificationResponseAsync().catch(() => {});
    });

    return () => {
      notificationResponseListener.current?.remove();
    };
  }, [router]);
};
